<?php
/** Private, database-independent technical error journal. Never stores request bodies. */
if(defined('STORE_ERRORS_READY'))return;
define('STORE_ERRORS_READY',true);
require_once __DIR__.'/config.php';
$GLOBALS['error_reserve']=str_repeat(' ',131072);
function error_clean(string $v,int $limit=2000):string{$root=dirname(__DIR__);$v=str_replace($root,'[app]',$v);$v=preg_replace('~(https?://[^\s?]+)\?[^\s]+~','$1?[query redacted]',$v);$v=preg_replace('/(?:Bearer\s+)[A-Za-z0-9._~+\/=\-]+/i','Bearer [REDACTED]',$v);$v=preg_replace('/((?:password|passwd|secret|token|api[-_ ]?key|authorization|cookie)\s*[=:]\s*)[^\s,;]+/i','$1[REDACTED]',$v);$v=preg_replace('/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i','[email redacted]',$v);$v=preg_replace('/(?<!\d)(?:\+?88)?01[3-9]\d{8}(?!\d)/','[phone redacted]',$v);return function_exists('mb_substr')?mb_substr($v,0,$limit):substr($v,0,$limit);}
function error_route(string $url):string{$parts=parse_url($url);$path=$parts['path']??'/';$hash=$parts['fragment']??'';$hash=explode('?',$hash)[0];$path=preg_replace('#/product/[^/]+#','/product/[slug]',$path);return error_clean($path.($hash?'#'.$hash:''),240);}
function error_journal_path():string{$db=$GLOBALS['env']['DB_DATABASE']??getenv('DB_DATABASE')?:'bonon';return app_storage_path('errors-').substr(hash('sha256',$db),0,12).'.jsonl';}
function error_journal_read():array{$file=error_journal_path();if(!is_file($file))return [];$fp=fopen($file,'r');if(!$fp)return [];flock($fp,LOCK_SH);$rows=[];while(($line=fgets($fp))!==false){$d=json_decode($line,true);if(is_array($d))$rows[]=$d;}flock($fp,LOCK_UN);fclose($fp);return $rows;}
function error_journal_clear():void{$file=error_journal_path();$fp=fopen($file,'c+');if(!$fp||!flock($fp,LOCK_EX))throw new RuntimeException('The error journal cannot be cleared. Check storage permissions.');ftruncate($fp,0);fflush($fp);flock($fp,LOCK_UN);fclose($fp);chmod($file,0600);}
function record_error(string $message,array $context=[]):string{static $busy=false,$count=0;if($busy||++$count>20)return ''; $busy=true;try{$id=bin2hex(random_bytes(10));$action=$context['action']??($_GET['action']??'page');$event=['id'=>$id,'time'=>gmdate('c'),'source'=>error_clean($context['source']??'server',20),'severity'=>in_array($context['severity']??'error',['error','warning','critical'],true)?($context['severity']??'error'):'error','action'=>preg_replace('/[^a-zA-Z0-9_:.\-]/','',substr((string)$action,0,80)),'route'=>error_route($context['route']??($_SERVER['REQUEST_URI']??'/worker')),'method'=>in_array($_SERVER['REQUEST_METHOD']??'CLI',['GET','POST','PUT','DELETE','PATCH','CLI'],true)?($_SERVER['REQUEST_METHOD']??'CLI'):'OTHER','status'=>(int)($context['status']??0),'message'=>error_clean($message),'user_id'=>(int)($_SESSION['uid']??0),'details'=>[]];foreach(['type','file','line','code','sqlstate','driver_code','stack','fields','hint','provider','operation','shipment_id']as $k)if(isset($context[$k])){$v=$context[$k];$event['details'][$k]=is_array($v)?array_map(fn($x)=>error_clean(is_scalar($x)?(string)$x:'[omitted]',300),array_slice($v,0,15)):error_clean((string)$v,$k==='stack'?4000:700);}$file=error_journal_path();$dir=dirname($file);if(!is_dir($dir))mkdir($dir,0700,true);$fp=fopen($file,'c+');if(!$fp||!flock($fp,LOCK_EX))return '';if(fstat($fp)['size']>5*1024*1024){$lines=explode("\n",trim(stream_get_contents($fp)));$keep=array_slice($lines,-1000);rewind($fp);ftruncate($fp,0);fwrite($fp,implode("\n",$keep)."\n");}fseek($fp,0,SEEK_END);fwrite($fp,json_encode($event,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE)."\n");fflush($fp);flock($fp,LOCK_UN);fclose($fp);chmod($file,0600);return $id;}catch(Throwable $e){error_log('Error journal unavailable; check private storage permissions.');return '';}finally{$busy=false;}}
function exception_context(Throwable $e):array{$c=['type'=>get_class($e),'file'=>error_clean($e->getFile(),250),'line'=>$e->getLine()];$trace=[];foreach(array_slice($e->getTrace(),0,12)as $t)$trace[]=error_clean(($t['file']??'[internal]').':'.($t['line']??0).' '.($t['class']??'').($t['type']??'').($t['function']??''),350);$c['stack']=implode("\n",$trace);if($e instanceof PDOException){$c['sqlstate']=$e->errorInfo[0]??$e->getCode();$c['driver_code']=$e->errorInfo[1]??0;}return $c;}
function exception_safe_message(Throwable $e):string{if($e instanceof PDOException)return match((int)($e->errorInfo[1]??0)){1062=>'A unique database value already exists. Check the product URL or account identifier.',1406=>'A value exceeds the database field length.',1364=>'A required database field is missing.',1045=>'Database authentication failed. Check server configuration.',1146=>'A required database table is missing. Run the upgrade migrations.',1054=>'A required database column is missing. Run the upgrade migrations.',default=>'Database operation failed. Technical codes and call location are available in the error details.'};return error_clean($e->getMessage());}
set_error_handler(function($severity,$message,$file,$line){if(!(error_reporting()&$severity))return false;record_error($message,['source'=>'php','severity'=>'warning','type'=>'PHP '.$severity,'file'=>$file,'line'=>$line]);return false;});
set_exception_handler(function(Throwable $e){$GLOBALS['error_reserve']='';$id=record_error(exception_safe_message($e),['severity'=>'critical']+exception_context($e));if(!headers_sent()){http_response_code(500);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');}echo json_encode(['error'=>'The request could not be completed. Contact the administrator with the error reference.','error_id'=>$id]);});
register_shutdown_function(function(){$last=error_get_last();if($last&&in_array($last['type'],[E_ERROR,E_PARSE,E_CORE_ERROR,E_COMPILE_ERROR],true)){$GLOBALS['error_reserve']='';record_error($last['message'],['source'=>'php','severity'=>'critical','type'=>'Fatal PHP error','file'=>$last['file'],'line'=>$last['line']]);}});
ini_set('display_errors','0');
